def gen(rng):
    def enc(d, k):
        n = len(d)
        rows = ['X' * r + d + 'X' * (k - 1 - r) for r in range(k)]
        return ''.join(rows[r][c] for c in range(n + k - 1) for r in range(k))

    def fmt(d, k):
        return str(k) + '\n' + enc(d, k)

    def digits(n):
        return ''.join(rng.choice('0123456789') for _ in range(n))

    tests = [fmt('5231', 3), fmt('7', 1), fmt('7', 4), fmt('0', 1), fmt('1000', 2), fmt('00', 3), fmt('123456789', 1)]
    for _ in range(25):
        n = rng.randint(1, 12)
        k = rng.randint(1, 8)
        tests.append(fmt(digits(n), k))
    tests.append(fmt(digits(100000), 9))
    tests.append(fmt(digits(1), 1000))
    tests.append(fmt(digits(100000), 1))
    tests.append(fmt(digits(3000), 300))
    tests.append(fmt(digits(1000), 500))
    return tests
